/*
|--------------------------------------------------------------------------
| FUNCION BLINDADA PARA TEXTO CMS
|--------------------------------------------------------------------------
*/

function cms_text($value)
{
if(is_array($value)){
$value = $value['es'] ?? reset($value);
}

$value = $value ?? '';

$value = str_replace('&nbsp;',' ',$value);

return trim($value);
}

